#include "vos/container.hpp"
namespace vos {
static void u16(std::vector<uint8_t>&o,uint16_t v){o.push_back(v&255);o.push_back((v>>8)&255);}static void u32(std::vector<uint8_t>&o,uint32_t v){for(int i=0;i<4;i++)o.push_back((v>>(8*i))&255);}static void u64(std::vector<uint8_t>&o,uint64_t v){for(int i=0;i<8;i++)o.push_back((v>>(8*i))&255);}static uint32_t r32(const std::vector<uint8_t>&b,size_t p){return (uint32_t)b[p]|((uint32_t)b[p+1]<<8)|((uint32_t)b[p+2]<<16)|((uint32_t)b[p+3]<<24);}static uint64_t r64(const std::vector<uint8_t>&b,size_t p){uint64_t v=0;for(int i=0;i<8;i++)v|=((uint64_t)b[p+i])<<(8*i);return v;}
std::vector<uint8_t> makeContainer(std::string magic,uint16_t major,uint16_t minor,const std::vector<Section>&secs){if(magic.size()!=4)throw std::runtime_error("container magic must be four bytes");std::vector<uint8_t>o(magic.begin(),magic.end());u16(o,major);u16(o,minor);u32(o,(uint32_t)secs.size());const uint64_t header=12+secs.size()*32ULL;uint64_t off=header;for(auto&s:secs){std::array<char,16>n{};std::copy_n(s.name.data(),std::min<size_t>(15,s.name.size()),n.data());o.insert(o.end(),(uint8_t*)n.data(),(uint8_t*)n.data()+16);u64(o,off);u64(o,s.data.size());off+=s.data.size();}for(auto&s:secs)o.insert(o.end(),s.data.begin(),s.data.end());return o;}
std::string containerInfo(const std::vector<uint8_t>&b){if(b.size()<12)throw std::runtime_error("file is too small");std::ostringstream o;o<<"magic="<<std::string((char*)b.data(),4)<<" version="<<(int)b[4]<<'.'<<(int)b[6]<<" sections="<<r32(b,8)<<"\n";uint32_t n=r32(b,8);for(uint32_t i=0;i<n;i++){size_t p=12+i*32;if(p+32>b.size())throw std::runtime_error("invalid section table");std::string name((char*)&b[p],16);name=name.c_str();o<<"  "<<name<<" offset="<<r64(b,p+16)<<" size="<<r64(b,p+24)<<"\n";}return o.str();}
}
